function fmt(n){return Math.round(n).toLocaleString('ru-RU');}
function fmtDate(s){if(!s)return'';try{return new Date(s).toLocaleDateString('ru-RU');}catch(e){return s;}}
function fmtNum(n){return String(n).padStart(11,'0');}
function numToWords(n){
  var u=['','один','два','три','четыре','пять','шесть','семь','восемь','девять','десять','одиннадцать','двенадцать','тринадцать','четырнадцать','пятнадцать','шестнадцать','семнадцать','восемнадцать','девятнадцать'];
  var t=['','','двадцать','тридцать','сорок','пятьдесят','шестьдесят','семьдесят','восемьдесят','девяносто'];
  var h=['','сто','двести','триста','четыреста','пятьсот','шестьсот','семьсот','восемьсот','девятьсот'];
  if(n===0)return 'ноль тенге 00 тиын';
  var r=Math.round(n),tiin=Math.round((n-r)*100),res='';
  function g(x){var a=Math.floor(x/100),b=Math.floor((x%100)/10),c=x%10,s='';
    if(a)s+=h[a]+' ';if(b===1)s+=u[x%100]+' ';else{if(b)s+=t[b]+' ';if(c)s+=u[c]+' ';}return s;}
  if(r>=1000000){var mm=Math.floor(r/1000000);res+=g(mm)+(mm%10===1&&mm%100!==11?' миллион':(mm%10>=2&&mm%10<=4&&(mm%100<10||mm%100>=20)?' миллиона':' миллионов'))+' ';r%=1000000;}
  if(r>=1000){var k=Math.floor(r/1000);res+=g(k).replace('один ','одна ').replace('два ','две ')+(k%10===1&&k%100!==11?' тысяча':(k%10>=2&&k%10<=4&&(k%100<10||k%100>=20)?' тысячи':' тысяч'))+' ';r%=1000;}
  if(r>0)res+=g(r);
  return res.trim()+' тенге '+(tiin<10?'0':'')+tiin+' тиын';
}
// ── Печать — единая реализация для всех вкладок ──────────────
var _stamps = {};  // {kp: base64, sc: base64}

function loadStamp(input) {
  var file = input.files[0]; if (!file) return;
  var pfx  = input.id.startsWith('kp__') ? 'kp' : 'sc';
  var reader = new FileReader();
  reader.onload = function(e) {
    var data = e.target.result;
    _stamps[pfx] = data;
    stampApply(pfx, data);
    var saveBtn = document.getElementById(pfx + '__stamp_save_btn');
    if (saveBtn) saveBtn.style.display = 'inline-block';
  };
  reader.readAsDataURL(file);
}

function saveStamp() {
  var pfx = _activePanel === 'kp' ? 'kp' : 'sc';
  var data = _stamps[pfx];
  if (!data) { showBinToast('⚠️ Сначала загрузите печать!', 'warn'); return; }
  var key = pfx === 'kp' ? 'nemo_stamp' : 'nemo_stamp_inv';
  try {
    localStorage.setItem(key, data);
    stampSaveToCloud();
    showBinToast('✅ Печать сохранена', 'success');
    var btn = document.getElementById(pfx + '__stamp_save_btn');
    if (btn) { btn.textContent = 'Сохранено!'; setTimeout(function(){ btn.textContent = 'Сохранить печать'; }, 2000); }
  } catch(e) { showBinToast('❌ Файл слишком большой для сохранения', 'warn'); }
}

function removeStamp() {
  var pfx = _activePanel === 'kp' ? 'kp' : 'sc';
  var key = pfx === 'kp' ? 'nemo_stamp' : 'nemo_stamp_inv';
  _stamps[pfx] = null;
  localStorage.removeItem(key);
  stampApply(pfx, null);
  stampSaveToCloud();
}

function stampApply(pfx, data) {
  var img     = document.getElementById(pfx + '__stamp_img');
  var preview = document.getElementById(pfx + '__stamp_preview');
  var empty   = document.getElementById(pfx + '__stamp_empty');
  var saveBtn = document.getElementById(pfx + '__stamp_save_btn');
  if (data) {
    if (img)     img.src = data;
    if (preview) preview.style.display = 'flex';
    if (empty)   empty.style.display   = 'none';
  } else {
    if (img)     img.src = '';
    if (preview) preview.style.display = 'none';
    if (empty)   empty.style.display   = 'inline';
    if (saveBtn) saveBtn.style.display = 'none';
    var upload = document.getElementById(pfx + '__stamp_upload');
    if (upload) upload.value = '';
  }
}

// ── Облачное сохранение печатей ──────────────────────────────
function stampSaveToCloud() {
  if (!ghCfg().token) return;
  var payload = {
    kp:         _stamps.kp  || null,
    sc:         _stamps.sc  || null,
    updated_at: new Date().toISOString()
  };
  var path = GH_PATH + '/stamps.json';
  ghGetFile(path).then(function(file) {
    return ghPutFile(path, payload, '🖨 Печати обновлены', file ? file.sha : null);
  }).catch(function(){});
}

function stampLoadFromCloud() {
  // Сначала загружаем из localStorage
  var kpLocal = localStorage.getItem('nemo_stamp');
  var scLocal = localStorage.getItem('nemo_stamp_inv');
  if (kpLocal) { _stamps.kp = kpLocal; stampApply('kp', kpLocal); }
  if (scLocal) { _stamps.sc = scLocal; stampApply('sc', scLocal); }

  // Потом пробуем облако (может быть свежее)
  if (!ghCfg().token) return;
  var path = GH_PATH + '/stamps.json';
  ghGetFile(path).then(function(file) {
    if (!file) return;
    var d = JSON.parse(decodeURIComponent(escape(atob(file.content.replace(/\s/g,'')))));
    if (d.kp  && d.kp  !== _stamps.kp)  { _stamps.kp  = d.kp;  stampApply('kp', d.kp);  localStorage.setItem('nemo_stamp', d.kp); }
    if (d.sc  && d.sc  !== _stamps.sc)  { _stamps.sc  = d.sc;  stampApply('sc', d.sc);  localStorage.setItem('nemo_stamp_inv', d.sc); }
  }).catch(function(){});
}

function initAllStamps() {
  stampLoadFromCloud();
}



