const LOGO_B64 = '';
let sc_items=[], sc_itemId=0;

function fmt(n){return Number(n).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})}

function numToWords(n){
  const units=['','один','два','три','четыре','пять','шесть','семь','восемь','девять','десять','одиннадцать','двенадцать','тринадцать','четырнадцать','пятнадцать','шестнадцать','семнадцать','восемнадцать','девятнадцать'];
  const tens=['','','двадцать','тридцать','сорок','пятьдесят','шестьдесят','семьдесят','восемьдесят','девяносто'];
  const hundreds=['','сто','двести','триста','четыреста','пятьсот','шестьсот','семьсот','восемьсот','девятьсот'];
  if(n===0)return'ноль тенге 00 тиын';
  let r=Math.round(n); let tiin=Math.round((n-r)*100); let result='';
  let mil=Math.floor(r/1000000); if(mil>0){result+=mil+' миллион'+(mil>1?'ов':'')+' ';r-=mil*1000000;}
  let th=Math.floor(r/1000);
  if(th>0&&th<20){const tw=['','одна тысяча','две тысячи','три тысячи','четыре тысячи','пять тысяч','шесть тысяч','семь тысяч','восемь тысяч','девять тысяч','десять тысяч','одиннадцать тысяч','двенадцать тысяч','тринадцать тысяч','четырнадцать тысяч','пятнадцать тысяч','шестнадцать тысяч','семнадцать тысяч','восемнадцать тысяч','девятнадцать тысяч'];result+=tw[th]+' ';r-=th*1000;}
  else if(th>=20){result+=tens[Math.floor(th/10)]+' ';if(th%10>0)result+=units[th%10]+' тысяч ';else result+='тысяч ';r-=th*1000;}
  let h=Math.floor(r/100); if(h>0){result+=hundreds[h]+' ';r-=h*100;}
  if(r>0&&r<20){result+=units[r]+' ';}else if(r>=20){result+=tens[Math.floor(r/10)]+' ';if(r%10>0)result+=units[r%10]+' ';}
  result=result.trim()+' тенге '+(tiin<10?'0':'')+tiin+' тиын';
  return result.charAt(0).toUpperCase()+result.slice(1);
}

function sc_addItem(){const id=++sc_itemId;sc_items.push({id,name:'',qty:1,unit:'шт.',price:0});sc_renderItems()}
function sc_removeItem(id){sc_items=sc_items.filter(i=>i.id!==id);sc_renderItems()}


function sc_renderItems(){
  const tbody=document.getElementById('sc__items-body');
  tbody.innerHTML='';
  sc_items.forEach(function(item,rowIdx){
    const tr=document.createElement('tr');
    function td(){ const t=document.createElement('td'); tr.appendChild(t); return t; }

    // № (номер строки)
    const numTd=td(); numTd.style.textAlign='center'; numTd.style.color='#888'; numTd.textContent=rowIdx+1;

    // Наименование — текстовое поле, используем input событие для плавного ввода
    const nameTd=td();
    const nameInp=document.createElement('input');
    nameInp.value=item.name||''; nameInp.placeholder='Наименование товара';
    nameInp.addEventListener('input',function(){item.name=this.value; scSave();});
    nameTd.appendChild(nameInp);

    // Кол-во
    const qtyTd=td();
    const qtyInp=document.createElement('input');
    qtyInp.type='number'; qtyInp.min='0.001'; qtyInp.step='0.001';
    qtyInp.value=item.qty||1; qtyInp.style.textAlign='center';
    qtyInp.addEventListener('change',function(){
      item.qty=+this.value||0;
      totTd.textContent=fmt(item.qty*item.price)+' ₸';
      sc_calcTotals(); scSave();
    });
    qtyTd.appendChild(qtyInp);

    // Ед.
    const unitTd=td();
    const unitInp=document.createElement('input');
    unitInp.value=item.unit||'шт.'; unitInp.placeholder='шт.';
    unitInp.style.width='50px';
    unitInp.addEventListener('input',function(){item.unit=this.value; scSave();});
    unitTd.appendChild(unitInp);

    // Цена
    const priceTd=td();
    const priceInp=document.createElement('input');
    priceInp.type='number'; priceInp.min='0'; priceInp.value=item.price||0;
    priceInp.addEventListener('change',function(){
      item.price=+this.value||0;
      totTd.textContent=fmt(item.qty*item.price)+' ₸';
      sc_calcTotals(); scSave();
    });
    priceTd.appendChild(priceInp);

    // Сумма (readonly)
    const totTd=td(); totTd.className='total';
    totTd.textContent=fmt((item.qty||0)*(item.price||0))+' ₸';

    // Удалить
    const delTd=td();
    const btn=document.createElement('button'); btn.className='remove-btn'; btn.textContent='×';
    btn.addEventListener('click',function(){sc_removeItem(item.id);});
    delTd.appendChild(btn);

    tbody.appendChild(tr);
  });
  sc_calcTotals();
  scSave();
}

function sc_updateItem(id,field,val){const item=sc_items.find(i=>i.id===id);if(item){item[field]=val;sc_renderItems()}}

function sc_calcTotals(){
  const total=sc_items.reduce((s,i)=>s+i.qty*i.price,0);
  document.getElementById('sc__total').textContent=fmt(total);
}

function sc_getData(){
  const total=sc_items.reduce((s,i)=>s+i.qty*i.price,0);
  return{
    items:sc_items,
    client_company:document.getElementById('sc__client_company').value||'—',
    client_bin:document.getElementById('sc__client_bin').value||'—',
    client_address:document.getElementById('sc__client_address').value||'—',
    client_contract:document.getElementById('sc__client_contract').value||'',
    inv_number:document.getElementById('sc__inv_number').value||'00000000001',
    inv_date:document.getElementById('sc__inv_date').value||new Date().toLocaleDateString('ru-RU'),
    sc_items, total, vat:total*16/116, stamp:window._stampData||null
  }
}

function fmtDate(d){
  if(!d)return'—';
  const months=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
  const parts=d.split('-');
  if(parts.length===3)return parts[2]+' '+months[parseInt(parts[1])-1]+' '+parts[0];
  return d;
}

