function sc_downloadPDF(){
  const content=document.getElementById('sc__preview-content');
  if(!content||!content.innerHTML){sc_showPreviewForPDF();return;}
  const d=sc_getData();
  const printDiv=document.createElement('div');
  printDiv.id='inv-print-area';
  printDiv.innerHTML=content.innerHTML;
  printDiv.querySelectorAll('[contenteditable]').forEach(el=>{el.removeAttribute('contenteditable');el.style.outline='none';el.style.background='none';});
  const style=document.createElement('style');
  style.id='print-style';
  style.innerHTML=`
    @page{margin:0;size:A4}
    @media print{
      body>*:not(#inv-print-area){display:none!important}
      #inv-print-area{display:block!important;position:fixed;top:0;left:0;width:100%;padding:0.8cm 1.2cm;font-family:Arial,sans-serif;font-size:11px;color:#222;background:#fff;box-sizing:border-box}
      .inv-notice{font-size:10px;color:#555;text-align:center;margin-bottom:10px}
      .inv-requisites{width:100%;border-collapse:collapse;margin-bottom:12px;font-size:11px}
      .inv-requisites td{padding:4px 7px;border:1px solid #ccc;vertical-align:top}
      .inv-requisites .label{background:#f5f5f5;font-weight:700}
      .inv-header{display:flex;align-items:flex-start;gap:12px;margin-bottom:12px;padding-bottom:10px;border-bottom:2px solid #39B2D1}
      .inv-title{font-size:15px;font-weight:700;margin:12px 0 8px}
      .inv-party{margin-bottom:6px;font-size:11px}
      .inv-party b{display:inline-block;min-width:85px}
      .inv-table{width:100%;border-collapse:collapse;margin:10px 0;font-size:11px}
      .inv-table th{border:1px solid #ccc;padding:5px 7px;background:#f5f5f5;font-weight:700;text-align:center}
      .inv-table td{border:1px solid #ccc;padding:5px 7px;vertical-align:top}
      .inv-table td.num{text-align:center}
      .inv-table td.right{text-align:right}
      .inv-summary{text-align:right;font-size:12px;margin:6px 0}
      .inv-summary b{display:inline-block;min-width:130px;text-align:left}
      .inv-words{font-size:11px;margin:6px 0}
      .inv-footer{display:flex;justify-content:space-between;margin-top:20px;padding-top:12px;border-top:1px solid #ccc;font-size:11px;align-items:flex-end}
      .inv-sign{position:relative;min-width:200px}
      .inv-sign-label{margin-bottom:0}
      .inv-sign-line{border-bottom:1px solid #222;margin-top:80px;margin-bottom:4px;min-width:180px}
      .inv-sign-name{font-size:10px;color:#555}
    }
    #inv-print-area{display:none}
  `;
  const oldTitle=document.title;
  document.title=`Счёт на оплату ${d.inv_number}`;
  document.head.appendChild(style);
  document.body.appendChild(printDiv);
  window.print();
  setTimeout(()=>{
    document.title=oldTitle;
    if(document.getElementById('print-style'))document.head.removeChild(style);
    if(document.getElementById('inv-print-area'))document.body.removeChild(printDiv);
  },1500);
}

function sc_copyText(){
  const d=sc_getData();
  const rows=d.items.map((it,i)=>`${i+1}. ${it.name} — ${it.qty} ${it.unit} × ${fmt(it.price)} ₸ = ${fmt(it.qty*it.price)} ₸`).join('\n');
  const text=`СЧЁТ НА ОПЛАТУ №${d.inv_number}\nДата: ${fmtDate(d.inv_date)}\n\nПоставщик: ТОО «Nemo.kz», БИН 200740026179\nПокупатель: ${d.client_company}, БИН/ИИН ${d.client_bin}\nАдрес: ${d.client_address}\n${d.client_contract?'Договор: '+d.client_contract+'\n':''}\n${rows}\n\nИтого: ${fmt(d.total)} ₸\nВ том числе НДС: ${fmt(d.vat)} ₸\n${numToWords(d.total)}\n\nИИК: KZ428562203142893508 | Банк ЦентрКредит | БИК: KCJBKZKX`;
  navigator.clipboard.writeText(text).then(()=>showBinToast('✅ Текст скопирован','success'));
}

function scExportExcel() {
  if (typeof XLSX === 'undefined') { showBinToast('❌ XLSX не загружен', 'warn'); return; }
  var d = sc_getData();
  if (!d.items || !d.items.length) { showBinToast('⚠️ Нет позиций для экспорта', 'warn'); return; }

  var rows = [];
  rows.push(['СЧЁТ НА ОПЛАТУ № ' + (d.inv_number || '—')]);
  rows.push(['Дата:', fmtDate(d.inv_date) || '—']);
  rows.push([]);
  rows.push(['Поставщик:', 'ТОО «Nemo.kz»', 'БИН:', '200740026179']);
  rows.push(['Покупатель:', d.client_company || '—', 'БИН:', d.client_bin || '—']);
  rows.push(['Адрес:', d.client_address || '—']);
  if (d.client_contract) rows.push(['Договор:', d.client_contract]);
  rows.push([]);
  rows.push(['№', 'Наименование', 'Ед.изм.', 'Кол-во', 'Цена, ₸', 'Сумма, ₸']);
  d.items.forEach(function(it, i) {
    var sum = (it.qty || 0) * (it.price || 0);
    rows.push([i + 1, it.name || '', it.unit || 'шт.', it.qty || 0, it.price || 0, sum]);
  });
  rows.push([]);
  rows.push(['', '', '', '', 'Итого:', d.total || 0]);
  rows.push(['', '', '', '', 'НДС:', d.vat || 0]);
  rows.push(['', '', '', '', 'ИТОГО с НДС:', d.total || 0]);
  rows.push([]);
  rows.push(['Банк:', 'Банк ЦентрКредит', 'БИК:', 'KCJBKZKX']);
  rows.push(['ИИК:', 'KZ428562203142893508']);

  var ws = XLSX.utils.aoa_to_sheet(rows);
  ws['!cols'] = [{wch:4},{wch:40},{wch:8},{wch:8},{wch:14},{wch:14}];

  var wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Счёт');
  var fname = 'Счёт_' + (d.inv_number || '001') + '_' + (d.client_company || '').slice(0, 20).replace(/[^а-яёА-ЯЁa-zA-Z0-9]/g,'_') + '.xlsx';
  XLSX.writeFile(wb, fname);
  showBinToast('✅ Счёт выгружен в Excel', 'success');
}


