var poa_items = [];
var poa_itemId = 0;

function poa_addItem() {
  poa_itemId++;
  poa_items.push({id: poa_itemId, name: '', unit: 'шт.', qty: 1});
  poa_renderItems();
}

function poa_removeItem(id) {
  poa_items = poa_items.filter(function(i){return i.id !== id;});
  poa_renderItems();
}

function poa_renderItems() {
  var tbody = document.getElementById('poa__items-body');
  if (!tbody) return;
  tbody.innerHTML = '';
  poa_items.forEach(function(it, idx) {
    var tr = document.createElement('tr');
    tr.innerHTML =
      '<td style="text-align:center;color:#888;">' + (idx+1) + '</td>' +
      '<td><input placeholder="Наименование товара" value="' + escHtml(it.name) + '" oninput="poa_items[' + idx + '].name=this.value;poaSave()"></td>' +
      '<td><input placeholder="шт." style="width:60px" value="' + escHtml(it.unit) + '" oninput="poa_items[' + idx + '].unit=this.value;poaSave()"></td>' +
      '<td><input type="number" min="1" value="' + it.qty + '" style="text-align:center" oninput="poa_items[' + idx + '].qty=+this.value||1;poaSave()"></td>' +
      '<td><button class="remove-btn" onclick="poa_removeItem(' + it.id + ')">×</button></td>';
    tbody.appendChild(tr);
  });
}

function escHtml(s) {
  return String(s||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function poa_numToWords(n) {
  var males=['','один','два','три','четыре','пять','шесть','семь','восемь','девять',
    'десять','одиннадцать','двенадцать','тринадцать','четырнадцать','пятнадцать',
    'шестнадцать','семнадцать','восемнадцать','девятнадцать'];
  var tens=['','','двадцать','тридцать','сорок','пятьдесят','шестьдесят','семьдесят','восемьдесят','девяносто'];
  var hunds=['','сто','двести','триста','четыреста','пятьсот','шестьсот','семьсот','восемьсот','девятьсот'];
  n = Math.round(Math.abs(n));
  if (n === 0) return 'ноль';
  function chunk(x) {
    var a=Math.floor(x/100), b=Math.floor((x%100)/10), c=x%10, s='';
    if(a) s+=hunds[a]+' ';
    if(b===1) s+=males[x%100]+' ';
    else { if(b) s+=tens[b]+' '; if(c) s+=males[c]+' '; }
    return s;
  }
  var res='';
  if(n>=1000){var k=Math.floor(n/1000); res+=chunk(k).replace('один ','одна ').replace('два ','две ')+(k%10===1&&k%100!==11?' тысяча':(k%10>=2&&k%10<=4&&(k%100<10||k%100>=20)?' тысячи':' тысяч'))+' '; n%=1000;}
  if(n>0) res+=chunk(n);
  return res.trim();
}

