    supplier: 'ТОО «Nemo.kz»',
    supplier_bin: '200740026179',
    supplier_iik: 'KZ428562203142893508',
    supplier_bank: 'АО «Банк ЦентрКредит»',
    supplier_bik: 'KCJBKZKX',
    supplier_address: 'Республика Казахстан, ВКО, г. Семей, ул. Мәңгілік ел, дом 9',
    // Реквизиты
    series: val('poa__series'),
    number: val('poa__number'),
    issue_date: val('poa__issue_date'),
    valid_until: val('poa__valid_until'),
    basis: val('poa__basis'),
    // Доверенное лицо
    person_fio: val('poa__person_fio'),
    person_position: val('poa__person_position'),
