// ═══════════════════════════════════════════════════════════════
// GITHUB CLOUD HISTORY — синхронизация и история документов
// ═══════════════════════════════════════════════════════════════

var GH_API  = 'https://api.github.com';
var GH_PATH = 'cloud-data';
var _ghCurrentType = null;
var _ghShaCache = {};

// ── Конфиг из localStorage ────────────────────────────────────
function ghCfg() {
  return {
    token: localStorage.getItem('gh_token') || '',
    owner: localStorage.getItem('gh_owner') || 'happen4ik',
    repo:  localStorage.getItem('gh_repo')  || 'nemo-b2b'
  };
}

// ── Базовые операции с GitHub API ────────────────────────────
function ghFetch(path, opts) {
  var c = ghCfg();
  if (!c.token) return Promise.reject(new Error('Токен не настроен'));
  var url = GH_API + '/repos/' + c.owner + '/' + c.repo + '/contents/' + path;
  // Правильное слияние заголовков — Authorization не теряется
  var baseHeaders = { 'Authorization': 'token ' + c.token, 'Accept': 'application/vnd.github.v3+json' };
  var extraHeaders = (opts && opts.headers) ? opts.headers : {};
  var mergedOpts = Object.assign({}, opts, { headers: Object.assign({}, baseHeaders, extraHeaders) });
  return fetch(url, mergedOpts);
}

function ghGetFile(path) {
  return ghFetch(path).then(function(r) {
    if (r.status === 404) return null;
    if (!r.ok) throw new Error('GitHub ' + r.status);
    return r.json();
  });
}

function ghPutFile(path, data, message, sha) {
  var body = { message: message, content: btoa(unescape(encodeURIComponent(JSON.stringify(data, null, 2)))) };
  if (sha) body.sha = sha;
  return ghFetch(path, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
    .then(function(r) { if (!r.ok) throw new Error('GitHub save: ' + r.status); return r.json(); });
}

function ghDeleteFile(path, message, sha) {
  return ghFetch(path, { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ message: message, sha: sha }) })
    .then(function(r) { if (!r.ok) throw new Error('GitHub delete: ' + r.status); return r.json(); });
}

// ── Загрузить историю ─────────────────────────────────────────
function ghLoadHistory(type) {
  var path = GH_PATH + '/' + type + '.json';
  return ghGetFile(path).then(function(file) {
    if (!file) return { docs: [], sha: null };
    _ghShaCache[type] = file.sha;
    try {
      var content = JSON.parse(decodeURIComponent(escape(atob(file.content.replace(/\s/g,'')))));
      return { docs: content.docs || [], sha: file.sha };
    } catch(e) { return { docs: [], sha: file.sha }; }
  });
}

// ── Контекст редактирования (какой документ сейчас открыт) ────
var _ghEditCtx = { kp: null, sc: null, poa: null };

function ghSetEditCtx(type, id, title) {
  _ghEditCtx[type] = { id: id, title: title };
  var bar     = document.getElementById(type + '__edit-bar');
  var titleEl = document.getElementById(type + '__edit-title');
  if (bar)     bar.classList.add('active');
  if (titleEl) titleEl.textContent = 'Редактируется: ' + title;
}

function ghClearEditCtx(type) {
  _ghEditCtx[type] = null;
  var bar = document.getElementById(type + '__edit-bar');
  if (bar) bar.classList.remove('active');
}

// ── Центральная функция сохранения в облако ───────────────────
function ghSaveToCloud(type, data, title, docId) {
  var path = GH_PATH + '/' + type + '.json';
  return ghLoadHistory(type).then(function(history) {
    var now      = new Date().toISOString();
    var existing = history.docs.find(function(d) { return d.id === docId; });
    if (existing) {
      existing.title      = title;
      existing.updated_at = now;
      existing.data       = data;
    } else {
      history.docs.unshift({ id: docId, title: title, created_at: now, updated_at: now, data: data });
    }
    return ghPutFile(path, { docs: history.docs }, '💾 ' + title, history.sha).then(function(res) {
      if (res && res.content) _ghShaCache[type] = res.content.sha;
    });
  });
}

// ── Явное сохранение (кнопка «💾 Сохранить») ─────────────────
function ghManualSave(type) {
  if (!ghCfg().token) { showGhSettings(); showBinToast('⚙️ Настройте GitHub токен', 'warn'); return; }
  var data  = ghCollectData(type);
  var title = ghMakeTitle(type, data);
  var ctx   = _ghEditCtx[type];
  var docId = ctx ? ctx.id : ghDocId(type, data);

  if (!docId) {
    showBinToast('⚠️ Укажите номер документа для сохранения', 'warn');
    return;
  }

  showBinToast('☁️ Сохраняю...', 'warn');
  ghSaveToCloud(type, data, title, docId).then(function() {
    if (ctx) {
      _ghEditCtx[type].title = title;
      var titleEl = document.getElementById(type + '__edit-title');
      if (titleEl) titleEl.textContent = 'Редактируется: ' + title;
    } else {
      ghSetEditCtx(type, docId, title);
    }
    showBinToast('✅ «' + title + '» сохранён в облако', 'success');
  }).catch(function(err) {
    showBinToast('❌ Ошибка: ' + (err.message || err), 'warn');
  });
}

// ── Сохранить как копию (новая запись) ───────────────────────
function ghSaveAsCopy(type) {
  if (!ghCfg().token) { showGhSettings(); return; }
  var data  = ghCollectData(type);
  var title = ghMakeTitle(type, data) + ' (копия)';
  var docId = type + '-copy-' + Date.now();

  showBinToast('☁️ Сохраняю копию...', 'warn');
  ghSaveToCloud(type, data, title, docId).then(function() {
    ghSetEditCtx(type, docId, title);
    showBinToast('✅ Сохранена новая копия: «' + title + '»', 'success');
  }).catch(function(err) {
    showBinToast('❌ Ошибка: ' + (err.message || err), 'warn');
  });
}

// ── Новый документ (сбросить контекст) ───────────────────────
function ghNewDoc(type) {
  ghClearEditCtx(type);
  if (type === 'kp')  kpReset  && kpReset();
  if (type === 'sc')  scReset  && scReset();
  if (type === 'poa') poaReset && poaReset();
  showBinToast('📄 Новый документ', 'success');
}

// ── Авто-сохранение при скачивании PDF ───────────────────────
function ghAutoSave(type) {
  if (!ghCfg().token) return;
  var data  = ghCollectData(type);
  var title = ghMakeTitle(type, data);
  var ctx   = _ghEditCtx[type];
  var docId = ctx ? ctx.id : ghDocId(type, data);
  if (!docId) return;

  ghSaveToCloud(type, data, title, docId).then(function() {
    if (!ctx) ghSetEditCtx(type, docId, title);
    showBinToast('☁️ «' + title + '» сохранён в историю', 'success');
  }).catch(function(err) { console.warn('ghAutoSave:', err.message); });
}

// ── Стабильный ID документа по номеру (для новых) ────────────
function ghDocId(type, data) {
  if (type === 'kp')  return data.kp_number  ? 'kp-'  + data.kp_number  : null;
  if (type === 'sc')  return data.inv_number  ? 'sc-'  + data.inv_number  : null;
  if (type === 'poa') return (data.series || data.number) ? 'poa-' + (data.series||'') + (data.number||'') : null;
  return null;
}

// ── Показать историю ─────────────────────────────────────────
function ghShowHistory(type) {
  var c = ghCfg();
  if (!c.token) { showGhSettings(); showBinToast('⚙️ Сначала настройте GitHub токен', 'warn'); return; }

  _ghCurrentType = type;
  var icons = { kp: '📄', sc: '💰', poa: '📋' };
  var titles = { kp: 'История КП', sc: 'История счетов', poa: 'История доверенностей' };
  document.getElementById('gh-hist-icon').textContent = icons[type] || '📋';
  document.getElementById('gh-hist-title').textContent = titles[type] || 'История';
  document.getElementById('gh-hist-body').innerHTML = '<div class="gh-empty">⏳ Загружаю из облака...</div>';
  document.getElementById('gh-history-overlay').classList.add('show');
  document.body.style.overflow = 'hidden';

  ghLoadHistory(type).then(function(history) {
    ghRenderHistory(history.docs, type);
  }).catch(function(err) {
    document.getElementById('gh-hist-body').innerHTML = '<div class="gh-empty">❌ ' + (err.message || err) + '</div>';
  });
}

function ghCloseHistory() {
  document.getElementById('gh-history-overlay').classList.remove('show');
  document.body.style.overflow = '';
  _ghCurrentType = null;
}

function ghRenderHistory(docs, type) {
  var body    = document.getElementById('gh-hist-body');
  var editCtx = _ghEditCtx[type];
  if (!docs || !docs.length) {
    body.innerHTML = '<div class="gh-empty">📭 История пуста<br><small>Нажмите «☁️ Сохранить» или скачайте PDF</small></div>';
    return;
  }
  body.innerHTML = '';
  docs.forEach(function(doc) {
    var created   = new Date(doc.created_at).toLocaleDateString('ru-RU', { day:'2-digit', month:'2-digit', year:'numeric' });
    var updated   = new Date(doc.updated_at).toLocaleString('ru-RU', { day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit' });
    var isUpdated = doc.created_at !== doc.updated_at;
    var isEditing = editCtx && editCtx.id === doc.id;
    var card = document.createElement('div');
    card.className = 'gh-doc-card';
    if (isEditing) card.style.cssText = 'border-color:#2ea043;background:#f0fff6';
    card.innerHTML =
      '<div class="card-title">' + (isEditing ? '✏️ ' : '') + escHtml(doc.title) + '</div>' +
      '<div class="card-meta">' + (isEditing ? '<b style="color:#2ea043">Открыт для редактирования</b> · ' : '') +
        'Создан: ' + created + (isUpdated ? ' · Изменён: ' + updated : '') + '</div>' +
      '<div class="card-actions">' +
        '<button class="card-btn card-btn-open" onclick="ghLoadDoc(\'' + doc.id + '\',\'' + type + '\')">' +
          (isEditing ? '↩ Перезагрузить' : '✏️ Редактировать') + '</button>' +
        '<button class="card-btn card-btn-del" onclick="ghConfirmDelete(\'' + doc.id + '\',\'' + type + '\',\'' + escHtml(doc.title).replace(/\'/g,"&#39;") + '\')">🗑 Удалить</button>' +
      '</div>';
    body.appendChild(card);
  });
}

// ── Открыть документ из истории ──────────────────────────────
function ghLoadDoc(id, type) {
  ghLoadHistory(type).then(function(history) {
    var doc = history.docs.find(function(d) { return d.id === id; });
    if (!doc) { showBinToast('❌ Документ не найден', 'warn'); return; }
    ghCloseHistory();
    ghRestoreData(doc.data, type);
    ghSetEditCtx(type, doc.id, doc.title);
    var tabMap = { kp: 0, sc: 1, poa: 2 };
    var tabs   = document.querySelectorAll('.tab-btn');
    var panels = document.querySelectorAll('.sub-panel');
    if (tabs[tabMap[type]]) {
      tabs.forEach(function(t) { t.classList.remove('active'); });
      panels.forEach(function(p) { p.style.display = 'none'; });
      tabs[tabMap[type]].classList.add('active');
      panels[tabMap[type]].style.display = 'block';
    }
    showBinToast('✅ «' + doc.title + '» открыт для редактирования', 'success');
  }).catch(function(err) { showBinToast('❌ ' + (err.message || err), 'warn'); });
}

// ── Удалить документ ─────────────────────────────────────────
function ghConfirmDelete(id, type, title) {
  if (!confirm('Удалить «' + title + '»?\nДействие необратимо.')) return;
  showBinToast('🗑 Удаляю...', 'warn');
  ghLoadHistory(type).then(function(history) {
    history.docs = history.docs.filter(function(d) { return d.id !== id; });
    var path = GH_PATH + '/' + type + '.json';
    return ghPutFile(path, { docs: history.docs }, '🗑 Удалить ' + title, history.sha);
  }).then(function() {
    showBinToast('✅ Документ удалён', 'success');
    ghShowHistory(type);
  }).catch(function(err) {
    showBinToast('❌ ' + (err.message || err), 'warn');
  });
}

// ── Собрать текущие данные формы ─────────────────────────────
function ghCollectData(type) {
  function val(id) { var el = document.getElementById(id); return el ? el.value : ''; }
  if (type === 'kp') {
    return {
      client_company: val('kp__client_company'), client_bin: val('kp__client_bin'),
      kp_number: val('kp__kp_number'), kp_date: val('kp__kp_date'),
      kp_valid_days: val('kp__kp_valid_days'), manager_name: val('kp__manager_name'),
      manager_phone: val('kp__manager_phone'), payment_terms: val('kp__payment_terms'),
      delivery_terms: val('kp__delivery_terms'), extra_notes: val('kp__extra_notes'),
      items: (typeof kp_items !== 'undefined' ? kp_items : [])
    };
  }
  if (type === 'sc') {
    return {
      client_company: val('sc__client_company'), client_bin: val('sc__client_bin'),
      client_address: val('sc__client_address'), client_contract: val('sc__client_contract'),
      inv_number: val('sc__inv_number'), inv_date: val('sc__inv_date'),
      items: (typeof sc_items !== 'undefined' ? sc_items : [])
    };
  }
  if (type === 'poa') {
    return poa_getData ? poa_getData() : {};
  }
  return {};
}

// ── Восстановить данные в форму ───────────────────────────────
function ghRestoreData(data, type) {
  function sv(id, val) {
    if (val == null) return;
    var el = document.getElementById(id);
    if (el) { el.value = val; el.dispatchEvent(new Event('input')); el.dispatchEvent(new Event('change')); }
  }
  if (type === 'kp') {
    sv('kp__client_company', data.client_company); sv('kp__client_bin', data.client_bin);
    sv('kp__kp_number', data.kp_number); sv('kp__kp_date', data.kp_date);
    sv('kp__kp_valid_days', data.kp_valid_days); sv('kp__payment_terms', data.payment_terms);
    sv('kp__delivery_terms', data.delivery_terms); sv('kp__extra_notes', data.extra_notes);
    if (data.items && data.items.length) {
      kp_items = data.items.map(function(it,i){ return Object.assign({id:i+1},it); });
      kp_itemId = kp_items.length; renderItems();
    }
    kpSave();
  }
  if (type === 'sc') {
    sv('sc__client_company', data.client_company); sv('sc__client_bin', data.client_bin);
    sv('sc__client_address', data.client_address); sv('sc__client_contract', data.client_contract);
    sv('sc__inv_number', data.inv_number); sv('sc__inv_date', data.inv_date);
    if (data.items && data.items.length) {
      sc_items = data.items.map(function(it,i){ return Object.assign({id:i+1},it); });
      sc_itemId = sc_items.length; sc_renderItems();
    }
    scSave();
  }
  if (type === 'poa') {
    var fields = ['org_name','org_bin','org_address','series','number','issue_date','valid_until',
      'basis','person_fio','person_position','pass_number','pass_issued_by','pass_issued_date',
      'head_fio','chief_accountant'];
    fields.forEach(function(f) { sv('poa__' + f, data[f]); });
    if (data.items && data.items.length) {
      poa_items = data.items.map(function(it,i){ return Object.assign({id:i+1},it); });
      poa_itemId = poa_items.length; poa_renderItems();
    }
    poaSave();
  }
}

// ── Заголовок документа ──────────────────────────────────────
function ghMakeTitle(type, data) {
  if (type === 'kp') return 'КП №' + (data.kp_number||'—') + (data.client_company ? ' — ' + data.client_company : '');
  if (type === 'sc') return 'Счёт №' + (data.inv_number||'—') + (data.client_company ? ' — ' + data.client_company : '');
  if (type === 'poa') return 'Доверенность ' + ((data.series||'') + (data.number||'—')) + (data.org_name ? ' — ' + data.org_name : '');
  return 'Документ';
}

// ── Settings UI ───────────────────────────────────────────────
function showGhSettings() {
  var c = ghCfg();
  document.getElementById('gh-token-input').value = c.token;
  document.getElementById('gh-owner-input').value = c.owner;
  document.getElementById('gh-repo-input').value  = c.repo;
  document.getElementById('gh-settings-modal').classList.add('show');
  document.getElementById('gh-test-status').textContent = '';
}
function closeGhSettings() {
  document.getElementById('gh-settings-modal').classList.remove('show');
}
function ghSaveSettings() {
  localStorage.setItem('gh_token', document.getElementById('gh-token-input').value.trim());
  localStorage.setItem('gh_owner', document.getElementById('gh-owner-input').value.trim() || 'happen4ik');
  localStorage.setItem('gh_repo',  document.getElementById('gh-repo-input').value.trim()  || 'nemo-b2b');
  ghUpdateStatusBtn();
  closeGhSettings();
  showBinToast('✅ Настройки сохранены', 'success');
}
function ghTestConnection() {
  var status = document.getElementById('gh-test-status');
  status.innerHTML = '<span style="color:#888">⏳ Проверяю...</span>';
  localStorage.setItem('gh_token', document.getElementById('gh-token-input').value.trim());
  localStorage.setItem('gh_owner', document.getElementById('gh-owner-input').value.trim() || 'happen4ik');
  localStorage.setItem('gh_repo',  document.getElementById('gh-repo-input').value.trim()  || 'nemo-b2b');
  var c = ghCfg();
  fetch(GH_API + '/repos/' + c.owner + '/' + c.repo, {
    headers: { 'Authorization': 'token ' + c.token, 'Accept': 'application/vnd.github.v3+json' }
  }).then(function(r) {
    if (r.ok) { status.innerHTML = '<span style="color:#1a7a4a">✅ Соединение работает!</span>'; ghUpdateStatusBtn(); }
    else if (r.status === 401) status.innerHTML = '<span style="color:#c0392b">❌ Неверный токен</span>';
    else if (r.status === 404) status.innerHTML = '<span style="color:#c0392b">❌ Репозиторий не найден</span>';
    else status.innerHTML = '<span style="color:#c0392b">❌ Ошибка: ' + r.status + '</span>';
  }).catch(function() { status.innerHTML = '<span style="color:#c0392b">❌ Нет соединения</span>'; });
}
function ghUpdateStatusBtn() {
  var btn = document.getElementById('gh-status-btn');
  if (!btn) return;
  btn.textContent = ghCfg().token ? '☁️✅' : '☁️';
  btn.title = ghCfg().token ? 'GitHub подключён — нажмите для настроек' : 'Настроить GitHub синхронизацию';
}

// ── Тема: светлая / тёмная ────────────────────────────────────
function toggleTheme() {
  var isDark = document.documentElement.getAttribute('data-theme') === 'dark';
  setTheme(isDark ? 'light' : 'dark');
}
function setTheme(theme) {
  document.documentElement.setAttribute('data-theme', theme);
  localStorage.setItem('nemo_theme', theme);
  var btn = document.getElementById('theme-toggle-btn');
  if (btn) btn.textContent = theme === 'dark' ? '☀️' : '🌙';
}
(function(){
  var saved = localStorage.getItem('nemo_theme');
  if (!saved && window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) saved = 'dark';
  if (saved) setTheme(saved);
})();

// ═══════════════════════════════════════════════════════════════
// CRM — Клиентская база
// ═══════════════════════════════════════════════════════════════

var crm_clients      = [];
var crm_filtered     = [];
var crm_statusFilter = '';

var CRM_STATUS = {
  active: { label: '🟢 Активный',  cls: 'crm-s-active' },
  work:   { label: '🔵 В работе',  cls: 'crm-s-work'   },
  won:    { label: '🏆 Сделка',    cls: 'crm-s-won'    },
  cold:   { label: '❄️ Холодный', cls: 'crm-s-cold'   },
  lost:   { label: '❌ Отказ',     cls: 'crm-s-lost'   },
};

function crmOpenModal(id) {
  var modal = document.getElementById('crm-modal');
  var title = document.getElementById('crm-modal-title');
  var flds  = ['edit-id','company','bin','status','contact','position','phone','email','address','deal-amount','notes'];
  if (id) {
    var c = crm_clients.find(function(c){ return c.id === id; });
    if (!c) return;
    title.textContent = '✏️ Редактировать клиента';
    document.getElementById('crm-edit-id').value      = c.id;
    document.getElementById('crm-company').value       = c.company      || '';
    document.getElementById('crm-bin').value           = c.bin          || '';
    document.getElementById('crm-status').value        = c.status       || 'active';
    document.getElementById('crm-contact').value       = c.contact      || '';
    document.getElementById('crm-position').value      = c.position     || '';
    document.getElementById('crm-phone').value         = c.phone        || '';
    document.getElementById('crm-email').value         = c.email        || '';
    document.getElementById('crm-address').value       = c.address      || '';
    document.getElementById('crm-deal-amount').value   = c.deal_amount  || '';
    document.getElementById('crm-notes').value         = c.notes        || '';
  } else {
    title.textContent = '+ Новый клиент';
    flds.forEach(function(f){ var el = document.getElementById('crm-' + f); if (el) el.value = ''; });
    document.getElementById('crm-status').value = 'active';
  }
  modal.classList.add('show');
  document.body.style.overflow = 'hidden';
  setTimeout(function(){ document.getElementById('crm-company').focus(); }, 100);
}

function crmCloseModal() {
  document.getElementById('crm-modal').classList.remove('show');
  document.body.style.overflow = '';
}

function crmSaveClient() {
  var company = document.getElementById('crm-company').value.trim();
  if (!company) { showBinToast('⚠️ Укажите название компании', 'warn'); return; }
  var id  = document.getElementById('crm-edit-id').value;
  var now = new Date().toISOString();
  var dateStr = new Date().toLocaleDateString('ru-RU', { day:'2-digit', month:'2-digit', year:'numeric' });
  var client = {
    id:           id || 'crm-' + Date.now(),
    created_at:   id ? ((crm_clients.find(function(c){ return c.id===id; })||{}).created_at || now) : now,
    updated_at:   now,
    last_contact: dateStr,
    company:      company,
    bin:          document.getElementById('crm-bin').value.trim(),
    status:       document.getElementById('crm-status').value,
    contact:      document.getElementById('crm-contact').value.trim(),
    position:     document.getElementById('crm-position').value.trim(),
    phone:        document.getElementById('crm-phone').value.trim(),
    email:        document.getElementById('crm-email').value.trim(),
    address:      document.getElementById('crm-address').value.trim(),
    deal_amount:  parseFloat(document.getElementById('crm-deal-amount').value) || 0,
    notes:        document.getElementById('crm-notes').value.trim(),
  };
  if (id) {
    var idx = crm_clients.findIndex(function(c){ return c.id===id; });
    if (idx>=0) crm_clients[idx] = client; else crm_clients.unshift(client);
  } else {
    crm_clients.unshift(client);
  }
  crmSaveLocal();
  crmFilter();
  crmUpdateStats();
  crmCloseModal();
  showBinToast((id ? '✅ Клиент обновлён: ' : '✅ Клиент добавлен: ') + company, 'success');
}

function crmDeleteClient(id) {
  var c = crm_clients.find(function(c){ return c.id===id; });
  if (!c || !confirm('Удалить клиента «' + c.company + '»?')) return;
  crm_clients = crm_clients.filter(function(c){ return c.id!==id; });
  crmSaveLocal();
  crmFilter();
  crmUpdateStats();
  showBinToast('🗑 Клиент удалён', 'success');
}

function crmSetStatus(btn, status) {
  crm_statusFilter = status;
  document.querySelectorAll('.crm-sf-btn').forEach(function(b){ b.classList.remove('active'); });
  btn.classList.add('active');
  crmFilter();
}

function crmFilter() {
  var q = (document.getElementById('crm-search') || {value:''}).value.toLowerCase().trim();
  crm_filtered = crm_clients.filter(function(c) {
    if (crm_statusFilter && c.status !== crm_statusFilter) return false;
    if (q) {
      var hay = (c.company+' '+c.contact+' '+c.phone+' '+c.email+' '+c.bin+' '+c.notes).toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });
  crmRenderTable();
}

function crmRenderTable() {
  var tbody = document.getElementById('crm-tbody');
  if (!tbody) return;
  if (!crm_filtered.length) {
    tbody.innerHTML = '<tr><td colspan="6" class="crm-empty">📭 Клиентов нет<br><small>Нажмите «+ Добавить клиента»</small></td></tr>';
    return;
  }
  tbody.innerHTML = crm_filtered.map(function(c) {
    var st  = CRM_STATUS[c.status] || CRM_STATUS.active;
    var id  = c.id;
    var amt = c.deal_amount > 0 ? '<br><small style="color:#39B2D1">' + Math.round(c.deal_amount).toLocaleString('ru-RU') + ' ₸</small>' : '';
    return '<tr onclick="crmOpenModal(\'' + id + '\')" style="cursor:pointer">' +
      '<td><b>' + escHtml(c.company) + '</b>' + (c.bin ? '<br><small style="color:#aaa">БИН: ' + escHtml(c.bin) + '</small>' : '') + amt + '</td>' +
      '<td>' + escHtml(c.contact||'—') + (c.position ? '<br><small style="color:#aaa">' + escHtml(c.position) + '</small>' : '') + '</td>' +
      '<td>' + escHtml(c.phone||'—') + (c.email ? '<br><small style="color:#aaa">' + escHtml(c.email) + '</small>' : '') + '</td>' +
      '<td><span class="crm-status ' + st.cls + '">' + st.label + '</span></td>' +
      '<td style="color:#aaa;font-size:12px">' + (c.last_contact||'—') + '</td>' +
      '<td onclick="event.stopPropagation()">' +
        '<div class="crm-actions">' +
          '<button class="crm-act-btn crm-act-kp" onclick="crmFillKP(\'' + id + '\')">📄 КП</button>' +
          '<button class="crm-act-btn crm-act-sc" onclick="crmFillSC(\'' + id + '\')">💰 Счёт</button>' +
          '<button class="crm-act-btn crm-act-del" onclick="crmDeleteClient(\'' + id + '\')">🗑</button>' +
        '</div>' +
      '</td>' +
    '</tr>';
  }).join('');
}

function crmUpdateStats() {
  function cnt(s){ return s ? crm_clients.filter(function(c){ return c.status===s; }).length : crm_clients.length; }
  function set(id,v){ var el=document.getElementById(id); if(el) el.textContent=v; }
  set('crm-cnt-all',    cnt(''));
  set('crm-cnt-active', cnt('active'));
  set('crm-cnt-work',   cnt('work'));
  set('crm-cnt-won',    cnt('won'));
  set('crm-cnt-cold',   cnt('cold'));
  set('crm-cnt-lost',   cnt('lost'));
}

function crmFillKP(id) {
  var c = crm_clients.find(function(c){ return c.id===id; }); if(!c) return;
  function sv(elId,val){ var el=document.getElementById(elId); if(el&&val) el.value=val; }
  sv('kp__client_company', c.company); sv('kp__client_bin', c.bin);
  if(typeof kpSave==='function') kpSave();
  showTopPanel('kp', document.querySelectorAll('.tab-btn')[0]);
  document.querySelectorAll('.tab-btn')[0].classList.add('active');
  showBinToast('✅ КП заполнен: ' + c.company, 'success');
}

function crmFillSC(id) {
  var c = crm_clients.find(function(c){ return c.id===id; }); if(!c) return;
  function sv(elId,val){ var el=document.getElementById(elId); if(el&&val) el.value=val; }
  sv('sc__client_company', c.company); sv('sc__client_bin', c.bin); sv('sc__client_address', c.address);
  if(typeof scSave==='function') scSave();
  showTopPanel('sc', document.querySelectorAll('.tab-btn')[1]);
  document.querySelectorAll('.tab-btn')[1].classList.add('active');
  showBinToast('✅ Счёт заполнен: ' + c.company, 'success');
}

function crmExportExcel() {
  if (typeof XLSX==='undefined') { showBinToast('❌ XLSX не загружен','warn'); return; }
  if (!crm_clients.length) { showBinToast('⚠️ Нет клиентов для экспорта','warn'); return; }
  var statusMap = { active:'Активный', work:'В работе', won:'Сделка', cold:'Холодный', lost:'Отказ' };
  var rows = [['Компания','БИН','Статус','Контакт','Должность','Телефон','Email','Адрес','Сумма ₸','Последнее касание','Примечания']];
  crm_clients.forEach(function(c) {
    rows.push([c.company||'',c.bin||'',statusMap[c.status]||'',c.contact||'',c.position||'',
               c.phone||'',c.email||'',c.address||'',c.deal_amount||0,c.last_contact||'',c.notes||'']);
  });
  var ws1 = XLSX.utils.aoa_to_sheet(rows);
  ws1['!cols'] = [30,14,12,20,18,16,24,30,14,14,30].map(function(w){ return {wch:w}; });

  var total = crm_clients.reduce(function(s,c){ return s+(c.deal_amount||0); },0);
  var sum2  = [['Статус','Количество','Сумма ₸']];
  Object.keys(statusMap).forEach(function(k) {
    var f = crm_clients.filter(function(c){ return c.status===k; });
    sum2.push([statusMap[k], f.length, f.reduce(function(s,c){ return s+(c.deal_amount||0); },0)]);
  });
  sum2.push(['','','']); sum2.push(['ИТОГО', crm_clients.length, total]);
  var ws2 = XLSX.utils.aoa_to_sheet(sum2);
  ws2['!cols'] = [{wch:16},{wch:12},{wch:18}];

  var wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws1, 'Клиенты');
  XLSX.utils.book_append_sheet(wb, ws2, 'Сводка');
  var date = new Date().toLocaleDateString('ru-RU').replace(/\./g,'-');
  XLSX.writeFile(wb, 'CRM_' + date + '.xlsx');
  showBinToast('✅ Excel выгружен: ' + crm_clients.length + ' клиентов', 'success');
}

function crmSaveLocal() {
  try { localStorage.setItem('nemo_crm', JSON.stringify(crm_clients)); } catch(e){}
}

function crmLoadLocal() {
  try {
    var raw = localStorage.getItem('nemo_crm');
    if (raw) crm_clients = JSON.parse(raw);
    crmFilter();
    crmUpdateStats();
  } catch(e){}
}

crmLoadLocal();

// ═══════════════════════════════════════════════════════════════
// КАТАЛОГ ТОВАРОВ — парсинг прайсов и управление
// ═══════════════════════════════════════════════════════════════

var cat_items        = [];   // все товары
var cat_filtered     = [];   // после фильтрации
var cat_page         = 0;
var cat_PAGE         = 50;
var cat_sortField    = 'name';
var cat_sortAsc      = true;
var cat_loadedFiles  = [];   // {name, count}

// ── Загрузка файлов ───────────────────────────────────────────
function catLoadFiles(files) {
  if (!files || !files.length) return;
  var zone = document.getElementById('cat-upload-zone');
  zone.querySelector('.duz-label').textContent = '⏳ Читаю файлы...';
  
  var promises = Array.from(files).map(function(file) {
    return catParseFile(file).then(function(items) {
      // Удаляем дубли того же файла если перезагружают
      cat_items = cat_items.filter(function(it) { return it._src !== file.name; });
      cat_loadedFiles = cat_loadedFiles.filter(function(f) { return f.name !== file.name; });
      cat_items = cat_items.concat(items);
      // Сохраняем имя поставщика (если уже было переименовано — сохраняем)
      var existing = cat_loadedFiles.find(function(f){ return f.name === file.name; });
      var supplierName = existing ? existing.supplierName : catCleanSupplierName(file.name);
      cat_loadedFiles.push({ name: file.name, supplierName: supplierName, count: items.length });
    }).catch(function(err) {
      showBinToast('❌ ' + file.name + ': ' + (err.message || err), 'warn');
    });
  });

  Promise.all(promises).then(function() {
    catSaveLocal();
    catBuildFilters();
    catFilter();
    catUpdateStats();
    catRenderFiles();
    zone.querySelector('.duz-label').textContent = 'Загрузите прайс-лист поставщика';
    showBinToast('✅ Загружено ' + cat_items.length + ' товаров', 'success');
  });
}

// ── Парсинг одного Excel файла ────────────────────────────────
function catParseFile(file) {
  return new Promise(function(resolve, reject) {
    if (typeof XLSX === 'undefined') { reject(new Error('XLSX не загружен')); return; }
    var reader = new FileReader();
    reader.onload = function(e) {
      try {
        var wb   = XLSX.read(e.target.result, { type: 'array' });
        var ws   = wb.Sheets[wb.SheetNames[0]];
        var rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false });
        var items = catAutoDetectAndParse(rows, file.name);
        resolve(items);
      } catch(err) { reject(err); }
    };
    reader.onerror = reject;
    reader.readAsArrayBuffer(file);
  });
}

// ── Авто-определение формата и парсинг ───────────────────────
function catAutoDetectAndParse(rows, srcName) {
  // Ищем строку с заголовками (первые 20 строк)
  for (var i = 0; i < Math.min(rows.length, 20); i++) {
    var row = rows[i].map(function(c) { return String(c).toLowerCase(); });
    var hasName  = row.some(function(c){ return c.includes('наименован') || c.includes('название'); });
    var hasPrice = row.some(function(c){ return c.includes('цен') || c.includes('price'); });
    if (hasName && hasPrice) {
      return catParseFlat(rows, i, srcName);
    }
    // Marvel: есть "вендор" или "vendor"
    var hasVendor = row.some(function(c){ return c.includes('вендор') || c === 'vendor'; });
    if (hasVendor) {
      return catParseMarvel(rows, i, srcName);
    }
  }
  // Иначе — иерархический формат (PriceMC)
  return catParseHierarchical(rows, srcName);
}

// ── Формат 1: Чистая таблица (Прайс) ─────────────────────────
function catParseFlat(rows, hdrIdx, srcName) {
  var hdr = rows[hdrIdx].map(function(c) { return String(c).toLowerCase(); });
  var col = {
    name:    catFindCol(hdr, ['наименован','название','name']),
    article: catFindCol(hdr, ['артикул','article','код','part']),
    cat:     catFindCol(hdr, ['категор','группа','раздел','group']),
    vendor:  catFindCol(hdr, ['произво','вендор','vendor','поставщик','бренд']),
    price:   catFindCol(hdr, ['цена kzt','цена, kzt','price kzt','цена тг','цена (тг)','цена']),
    currency:catFindCol(hdr, ['валют','currency']),
    qty:     catFindCol(hdr, ['кол-во','количест','qty','остат','свободно','stock']),
  };
  if (col.name < 0) return [];
  var items = [];
  for (var i = hdrIdx + 1; i < rows.length; i++) {
    var r    = rows[i];
    var name = String(r[col.name] || '').trim();
    if (!name) continue;
    var price = col.price >= 0 ? parseFloat(String(r[col.price]).replace(/[^\d.]/g,'')) : 0;
    if (isNaN(price)) price = 0;
    var currency = col.currency >= 0 ? String(r[col.currency]).trim().toUpperCase() : 'KZT';
    if (!currency || currency === 'NAN') currency = 'KZT';
    items.push({
      _id:      srcName + '-' + i,
      _src:     srcName,
      article:  col.article >= 0 ? String(r[col.article] || '').trim() : '',
      name:     name,
      category: col.cat    >= 0 ? String(r[col.cat]    || '').trim() : '',
      vendor:   col.vendor >= 0 ? String(r[col.vendor] || '').trim() : '',
      price:    price,
      currency: currency,
      price_kzt: currency === 'USD' ? price * catGetRate() : price,
      qty:      col.qty >= 0 ? (parseFloat(r[col.qty]) || 0) : 0,
    });
  }
  return items;
}

// ── Формат 2: Marvel (многоуровневые категории) ───────────────
function catParseMarvel(rows, hdrIdx, srcName) {
  var hdr = rows[hdrIdx].map(function(c) { return String(c).toLowerCase(); });
  var col = {
    cat1: catFindCol(hdr, ['категория 1','category 1','cat1']),
    cat2: catFindCol(hdr, ['категория 2','category 2','cat2']),
    cat3: catFindCol(hdr, ['категория 3','category 3','cat3']),
    vendor:  catFindCol(hdr, ['вендор','vendor']),
    article: catFindCol(hdr, ['артикул','article','part']),
    name:    catFindCol(hdr, ['наименован','название','name']),
    price:   catFindCol(hdr, ['цена','price']),
    currency:catFindCol(hdr, ['валют','currency']),
    free:    catFindCol(hdr, ['свободно','free','доступно']),
  };
  var items = [];
  for (var i = hdrIdx + 1; i < rows.length; i++) {
    var r    = rows[i];
    var name = String(r[col.name] || '').trim();
    if (!name) continue;
    var price = col.price >= 0 ? parseFloat(String(r[col.price]).replace(/[^\d.]/g,'')) : 0;
    if (isNaN(price) || price <= 0) continue;
    var currency = col.currency >= 0 ? String(r[col.currency] || 'USD').trim().toUpperCase() : 'USD';
    var cats = [r[col.cat1], r[col.cat2], r[col.cat3]].map(function(c){ return String(c||'').trim(); }).filter(Boolean);
    items.push({
      _id:      srcName + '-' + i,
      _src:     srcName,
      article:  col.article >= 0 ? String(r[col.article] || '').trim() : '',
      name:     catShortenName(name, 120),
      category: cats.join(' / '),
      vendor:   col.vendor >= 0 ? String(r[col.vendor] || '').trim() : '',
      price:    price,
      currency: currency,
      price_kzt: currency === 'USD' ? price * catGetRate() : price,
      qty:      col.free >= 0 ? (parseFloat(r[col.free]) || 0) : 0,
    });
  }
  return items;
}

// ── Формат 3: Иерархический (PriceMC) ────────────────────────
function catParseHierarchical(rows, srcName) {
  var items       = [];
  var currentCat  = '';
  for (var i = 0; i < rows.length; i++) {
    var row  = rows[i];
    var col0 = String(row[0] || '').trim();
    var col1 = String(row[1] || '').trim();
    var col3 = row[3];
    // Категория — col0 не пустой, col1 пустой, не заголовок
    if (col0 && !col1 && !['категория','nan','_'].includes(col0.toLowerCase())) {
      currentCat = col0;
      continue;
    }
    // Товар — col1 не пустой, col3 = цена
    if (col1 && col3 && col3 !== '_') {
      var price = parseFloat(String(col3).replace(/[^\d.]/g,''));
      if (!isNaN(price) && price > 0) {
        items.push({
          _id:      srcName + '-' + i,
          _src:     srcName,
          article:  '',
          name:     catShortenName(col1, 120),
          category: currentCat,
          vendor:   'HP',
          price:    price,
          currency: 'KZT',
          price_kzt: price,
          qty:      0,
        });
      }
    }
  }
  return items;
}

// ── Вспомогательные функции ───────────────────────────────────
function catFindCol(headers, keywords) {
  for (var i = 0; i < headers.length; i++) {
    var h = headers[i];
    for (var k = 0; k < keywords.length; k++) {
      if (h.includes(keywords[k])) return i;
    }
  }
  return -1;
}

function catShortenName(name, maxLen) {
  name = name.replace(/\s+/g, ' ').trim();
  return name.length > maxLen ? name.slice(0, maxLen) + '…' : name;
}

function catFmtPrice(it) {
  var kzt = Math.round(it.price_kzt || 0).toLocaleString('ru-RU');
  if (it.currency === 'USD') {
    return '<span class="cat-price-usd">$' + (it.price||0).toLocaleString('ru-RU', {maximumFractionDigits:0}) + ' ≈ </span>' +
           '<span class="cat-price">' + kzt + ' ₸</span>';
  }
  return '<span class="cat-price">' + kzt + ' ₸</span>';
}

function catGetRate() {
  var el = document.getElementById('cat-usd-rate');
  return el ? (parseFloat(el.value) || 480) : 480;
}

function catApplyRate() {
  var rate = catGetRate();
  cat_items.forEach(function(it) { if (it.currency === 'USD') it.price_kzt = it.price * rate; });
  localStorage.setItem('nemo_usd_rate', rate);
  catFilter();
}

// ── Фильтрация и сортировка ──────────────────────────────────
function catFilter() {
  var q         = (document.getElementById('cat-search').value || '').toLowerCase().trim();
  var supplierF = (document.getElementById('cat-supplier-filter') || {}).value || '';
  var catF      = (document.getElementById('cat-cat-filter') || {}).value || '';
  var vendorF   = (document.getElementById('cat-vendor-filter') || {}).value || '';
  var currF     = (document.getElementById('cat-currency-filter') || {}).value || '';

  cat_filtered = cat_items.filter(function(it) {
    if (supplierF && it._src !== supplierF) return false;
    if (catF    && it.category !== catF)    return false;
    if (vendorF && it.vendor   !== vendorF) return false;
    if (currF   && it.currency !== currF)   return false;
    if (q) {
      var hay = (it.name + ' ' + it.article + ' ' + it.vendor + ' ' + it.category).toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  cat_filtered.sort(function(a, b) {
    var av = a[cat_sortField] || '', bv = b[cat_sortField] || '';
    if (cat_sortField === '_supplierName') {
      var af = cat_loadedFiles.find(function(f){ return f.name === a._src; });
      var bf = cat_loadedFiles.find(function(f){ return f.name === b._src; });
      av = (af && af.supplierName) || a._src || '';
      bv = (bf && bf.supplierName) || b._src || '';
    }
    if (typeof av === 'number') return cat_sortAsc ? av - bv : bv - av;
    av = String(av).toLowerCase(); bv = String(bv).toLowerCase();
    return cat_sortAsc ? av.localeCompare(bv, 'ru') : bv.localeCompare(av, 'ru');
  });

  cat_page = 0;
  catRenderTable();
  catUpdateStats();
}

function catSort(field) {
  if (cat_sortField === field) cat_sortAsc = !cat_sortAsc;
  else { cat_sortField = field; cat_sortAsc = true; }
  catFilter();
}

// ── Рендер таблицы ───────────────────────────────────────────
function catRenderTable() {
  var tbody = document.getElementById('cat-tbody');
  if (!tbody) return;

  if (!cat_filtered.length) {
    tbody.innerHTML = '<tr><td colspan="7" class="cat-empty">😕 Ничего не найдено<br><small>Попробуйте изменить фильтры или загрузите прайс</small></td></tr>';
    document.getElementById('cat-pagination').innerHTML = '';
    return;
  }

  var start = cat_page * cat_PAGE;
  var end   = Math.min(start + cat_PAGE, cat_filtered.length);
  var page  = cat_filtered.slice(start, end);

  tbody.innerHTML = page.map(function(it) {
    var qtyHtml = it.qty > 0
      ? '<span class="cat-qty">' + Math.round(it.qty) + ' шт.</span>'
      : '<span class="cat-qty-zero">нет</span>';
    var fileInfo = cat_loadedFiles.find(function(f){ return f.name === it._src; }) || {};
    var supplierName = fileInfo.supplierName || it._src || '—';
    return '<tr>' +
      '<td style="white-space:nowrap;font-weight:600;color:#39B2D1;font-size:12px">' + escHtml(supplierName.slice(0,25)) + '</td>' +
      '<td style="white-space:nowrap;font-size:12px">' + escHtml(it.vendor || '—') + '</td>' +
      '<td><span style="font-size:11px;color:#888">' + escHtml((it.category || '').slice(0,35)) + '</span></td>' +
      '<td class="cat-article">' + escHtml(it.article || '—') + '</td>' +
      '<td><div class="cat-name" title="' + escHtml(it.name) + '">' + escHtml(it.name) + '</div></td>' +
      '<td style="text-align:right;white-space:nowrap">' + catFmtPrice(it) + '</td>' +
      '<td style="text-align:center">' + qtyHtml + '</td>' +
    '</tr>';
  }).join('');

  catRenderPagination();
}

function catRenderPagination() {
  var total = Math.ceil(cat_filtered.length / cat_PAGE);
  var pg    = document.getElementById('cat-pagination');
  if (!pg || total <= 1) { if (pg) pg.innerHTML = ''; return; }
  var html  = '';
  var s = Math.max(0, cat_page - 3), e = Math.min(total - 1, cat_page + 3);
  if (cat_page > 0) html += '<button class="cat-page-btn" onclick="catGoPage(' + (cat_page-1) + ')">← Пред</button>';
  if (s > 0)        html += '<button class="cat-page-btn" onclick="catGoPage(0)">1</button><span>…</span>';
  for (var i = s; i <= e; i++)
    html += '<button class="cat-page-btn' + (i===cat_page?' active':'') + '" onclick="catGoPage(' + i + ')">' + (i+1) + '</button>';
  if (e < total-1)       html += '<span>…</span><button class="cat-page-btn" onclick="catGoPage(' + (total-1) + ')">' + total + '</button>';
  if (cat_page < total-1) html += '<button class="cat-page-btn" onclick="catGoPage(' + (cat_page+1) + ')">След →</button>';
  pg.innerHTML = html;
}

function catGoPage(n) {
  cat_page = n;
  catRenderTable();
  var panel = document.getElementById('panel-cat');
  if (panel) panel.scrollTo(0, 0);
}

// ── Фильтры и статистика ─────────────────────────────────────
function catBuildFilters() {
  var supplierSel = document.getElementById('cat-supplier-filter');
  var prevSup = supplierSel ? supplierSel.value : '';
  if (supplierSel) supplierSel.innerHTML = '<option value="">Все прайсы (' + cat_loadedFiles.length + ')</option>' +
    cat_loadedFiles.map(function(f) {
      return '<option value="' + escHtml(f.name) + '"' + (f.name===prevSup?' selected':'') + '>' + escHtml(f.supplierName || f.name) + ' (' + f.count + ')</option>';
    }).join('');

  var cats = [...new Set(cat_items.map(function(it){ return it.category; }).filter(Boolean))].sort(function(a,b){ return a.localeCompare(b,'ru'); });
  var catSel = document.getElementById('cat-cat-filter');
  var prevCat = catSel ? catSel.value : '';
  if (catSel) catSel.innerHTML = '<option value="">Все категории (' + cats.length + ')</option>' +
    cats.map(function(c){ return '<option value="' + escHtml(c) + '"' + (c===prevCat?' selected':'') + '>' + escHtml(c.slice(0,55)) + '</option>'; }).join('');

  var vendors = [...new Set(cat_items.map(function(it){ return it.vendor; }).filter(Boolean))].sort(function(a,b){ return a.localeCompare(b,'ru'); });
  var vendorSel = document.getElementById('cat-vendor-filter');
  var prevVendor = vendorSel ? vendorSel.value : '';
  if (vendorSel) vendorSel.innerHTML = '<option value="">Все бренды (' + vendors.length + ')</option>' +
    vendors.map(function(v){ return '<option value="' + escHtml(v) + '"' + (v===prevVendor?' selected':'') + '>' + escHtml(v) + '</option>'; }).join('');
}

function catUpdateStats() {
  function s(id, v){ var el=document.getElementById(id); if(el) el.textContent=v; }
  s('cat-total-count',    cat_items.length.toLocaleString('ru-RU'));
  s('cat-vendor-count',   cat_loadedFiles.length);
  s('cat-filtered-count', cat_filtered.length.toLocaleString('ru-RU'));
}

// ── Файлы поставщиков ────────────────────────────────────────
function catRenderFiles() {
  var el = document.getElementById('cat-files-list');
  if (!el) return;
  el.innerHTML = '';
  cat_loadedFiles.forEach(function(f) {
    var tag = document.createElement('div');
    tag.className = 'cat-file-tag';
    var nameSpan = document.createElement('span');
    nameSpan.className = 'cat-supplier-name';
    nameSpan.title = 'Нажмите чтобы переименовать';
    nameSpan.textContent = f.supplierName || f.name;
    nameSpan.onclick = function() { catStartRename(f.name, tag, nameSpan); };
    var countSpan = document.createElement('span');
    countSpan.style.cssText = 'color:#39B2D1;font-size:11px';
    countSpan.textContent = '(' + f.count.toLocaleString('ru-RU') + ')';
    var delBtn = document.createElement('button');
    delBtn.title = 'Удалить'; delBtn.textContent = '×';
    delBtn.onclick = function() { catRemoveFile(f.name); };
    tag.appendChild(nameSpan); tag.appendChild(countSpan); tag.appendChild(delBtn);
    el.appendChild(tag);
  });
}

function catStartRename(srcName, tag, nameSpan) {
  var f = cat_loadedFiles.find(function(f){ return f.name === srcName; });
  if (!f) return;
  var input = document.createElement('input');
  input.className = 'cat-supplier-input';
  input.value = f.supplierName || f.name;
  input.maxLength = 60;
  tag.replaceChild(input, nameSpan);
  input.focus(); input.select();
  function save() {
    var newName = input.value.trim() || f.name;
    f.supplierName = newName;
    catSaveLocal(); catBuildFilters(); catRenderFiles();
    showBinToast('✅ Переименован: «' + newName + '»', 'success');
  }
  input.addEventListener('blur', save);
  input.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') input.blur();
    if (e.key === 'Escape') { input.value = f.supplierName || f.name; input.blur(); }
  });
}

function catCleanSupplierName(filename) {
  var name = filename.replace(/\.[^.]+$/, '');
  name = name.replace(/[_\s]+\d{2}[_\s]\d{2}[_\s]\d{4}.*/g, '');
  name = name.replace(/[_\s]+\d{4}[_\s]\d{2}[_\s]\d{2}.*/g, '');
  name = name.replace(/[_\s]+\d+[_\s]*$/g, '');
  name = name.replace(/[_]+/g, ' ').trim();
  name = name.replace(/\s+(Stock|Price|Прайс)\s*$/i, '').trim();
  return name || filename;
}

function catRemoveFile(name) {
  cat_items       = cat_items.filter(function(it){ return it._src !== name; });
  cat_loadedFiles = cat_loadedFiles.filter(function(f){ return f.name !== name; });
  catSaveLocal(); catBuildFilters(); catFilter(); catUpdateStats(); catRenderFiles();
  showBinToast('🗑 Прайс удалён', 'success');
}

function catClearAll() {
  if (!confirm('Очистить весь каталог?')) return;
  cat_items = []; cat_filtered = []; cat_loadedFiles = []; cat_page = 0;
  catSaveLocal(); catBuildFilters(); catFilter(); catUpdateStats(); catRenderFiles();
}

// ── localStorage + GitHub облако ─────────────────────────────
function catSaveLocal() {
  try { localStorage.setItem('nemo_catalog', JSON.stringify({ items: cat_items, files: cat_loadedFiles })); }
  catch(e) { console.warn('Catalog save:', e); }
  catSaveToCloud();
}

function catLoadLocal() {
  try {
    var raw = localStorage.getItem('nemo_catalog');
    if (raw) { var d = JSON.parse(raw); cat_items = d.items || []; cat_loadedFiles = d.files || []; }
    var rate = localStorage.getItem('nemo_usd_rate');
    if (rate) { var el = document.getElementById('cat-usd-rate'); if (el) el.value = rate; }
    var rr = catGetRate();
    cat_items.forEach(function(it){ if (it.currency === 'USD') it.price_kzt = it.price * rr; });
    catBuildFilters(); catFilter(); catUpdateStats(); catRenderFiles();
  } catch(e) {}
}

function catSaveToCloud() {
  if (!ghCfg().token) return;
  var data = { items: cat_items, files: cat_loadedFiles, saved_at: new Date().toISOString() };
  var path = GH_PATH + '/catalog.json';
  ghGetFile(path).then(function(file) {
    return ghPutFile(path, data, '📦 Каталог обновлён', file ? file.sha : null);
  }).catch(function(){});
}

function catLoadFromCloud() {
  if (!ghCfg().token) { catLoadLocal(); return; }
  var path = GH_PATH + '/catalog.json';
  ghGetFile(path).then(function(file) {
    if (!file) { catLoadLocal(); return; }
    var d = JSON.parse(decodeURIComponent(escape(atob(file.content.replace(/\s/g,'')))));
    if (!d.items || !d.items.length) { catLoadLocal(); return; }
    cat_items       = d.items;
    cat_loadedFiles = d.files || [];
    var rate = catGetRate();
    cat_items.forEach(function(it){ if (it.currency === 'USD') it.price_kzt = it.price * rate; });
    // Sync to localStorage
    localStorage.setItem('nemo_catalog', JSON.stringify({ items: cat_items, files: cat_loadedFiles }));
    catBuildFilters(); catFilter(); catUpdateStats(); catRenderFiles();
    if (d.saved_at) showBinToast('📦 Каталог загружен из облака (' + d.items.length.toLocaleString('ru-RU') + ' товаров)', 'success');
  }).catch(function(){ catLoadLocal(); });
}

// ── Drag & drop ──────────────────────────────────────────────
(function(){
  var zone = document.getElementById('cat-upload-zone');
  if (!zone) return;
  zone.addEventListener('dragover',  function(e){ e.preventDefault(); zone.classList.add('drag-over'); });
  zone.addEventListener('dragleave', function(){ zone.classList.remove('drag-over'); });
  zone.addEventListener('drop', function(e){
    e.preventDefault(); zone.classList.remove('drag-over');
    catLoadFiles(e.dataTransfer.files);
  });
})();

// Загрузить при старте (сначала из облака, потом из localStorage)
catLoadFromCloud();

